<?php

declare(strict_types=1);

namespace Sentinel\Services;

use DateTimeImmutable;
use PDOException;
use Sentinel\Core\HttpException;
use Sentinel\Core\RuntimeContext;
use Sentinel\Repositories\IncidentRepository;

final class IncidentManagementService
{
    private const SEVERITIES=['LOW','MEDIUM','HIGH','CRITICAL']; private const STATUSES=['OPEN','INVESTIGATING','RESOLVED','CLOSED','CANCELLED']; private const FIELDS=['site_id','employee_id','reporter_user_id','shift_assignment_id','patrol_session_id','incident_type','incident_category','severity','status','occurred_at','reported_at','description','actions_taken','resolution','closed_at'];
    private const TRANSITIONS=['OPEN'=>['INVESTIGATING','CANCELLED'],'INVESTIGATING'=>['RESOLVED','CANCELLED'],'RESOLVED'=>['CLOSED'],'CLOSED'=>[],'CANCELLED'=>[]];
    public function __construct(private readonly IncidentRepository $incidents,private readonly RuntimeContext $context,private readonly AuditService $audit){}
    public function listIncidents(array $filters=[]):array{if(array_diff(array_keys($filters),['site_id','employee_id','status','severity','incident_category','incident_type','date_from','date_to'])!==[])throw HttpException::unprocessable('Invalid incident filters.','invalid_incident_filters');return$this->incidents->listForCompany($filters);}
    public function getIncident(string $id):array{return$this->incidents->findByIdForCompany($id)??throw HttpException::notFound('Incident not found.','incident_not_found');}
    public function createIncident(array $input):array{$data=$this->fields($input,false);$data['incident_uuid']=uuid4();$data['incident_number']='INC-'.strtoupper(substr(str_replace('-','',uuid4()),0,12));$data['created_by_user_id']=$this->actor();$data['updated_by_user_id']=$this->actor();$this->relationships($data);$this->times($data);try{$incident=$this->incidents->createForCompany($data);}catch(PDOException){throw HttpException::conflict('Incident number is already in use.','incident_conflict');}$this->audit('created',$incident);return$incident;}
    public function updateIncident(string $id,array $input):array{$before=$this->getIncident($id);$patch=$this->fields($input,true);if($patch===[])throw HttpException::unprocessable('No editable incident fields were provided.','invalid_incident_update');$effective=array_merge($before,$patch);if(isset($patch['status'])&&$patch['status']!==$before['status']&&!in_array($patch['status'],self::TRANSITIONS[$before['status']]??[],true))throw HttpException::unprocessable('Incident status transition is invalid.','invalid_incident_transition');if(($effective['status']==='RESOLVED'||$effective['status']==='CLOSED')&&(!is_string($effective['resolution']??null)||trim($effective['resolution'])===''))throw HttpException::unprocessable('Resolved incidents require a resolution.','invalid_incident_resolution');if($effective['status']==='CLOSED'&&empty($effective['closed_at']))throw HttpException::unprocessable('Closed incidents require closed_at.','invalid_closed_at');$this->relationships($effective);$this->times($effective);$patch['updated_by_user_id']=$this->actor();try{$incident=$this->incidents->updateForCompany($id,$patch)??throw HttpException::notFound('Incident not found.','incident_not_found');}catch(PDOException){throw HttpException::conflict('Incident could not be updated.','incident_conflict');}$this->audit($before['status']===$incident['status']?'updated':'status_changed',$incident);return$incident;}
    private function fields(array $input,bool $update):array{if(array_diff(array_keys($input),self::FIELDS)!==[])throw HttpException::unprocessable('Invalid incident fields.','invalid_incident_request');$data=$input;foreach(['site_id','employee_id','reporter_user_id','shift_assignment_id','patrol_session_id']as$f)if(isset($data[$f])&&$data[$f]!==null)$data[$f]=$this->id($data[$f],$f);foreach(['incident_type','incident_category']as$f)if((!$update||array_key_exists($f,$data))&&(!is_string($data[$f]??null)||trim($data[$f])===''||strlen(trim($data[$f]))>100))throw HttpException::unprocessable('Incident field is invalid.','invalid_'.$f);foreach(['incident_type','incident_category']as$f)if(isset($data[$f]))$data[$f]=trim($data[$f]);if(!$update){foreach(['site_id','incident_type','incident_category','occurred_at','description']as$f)if(!array_key_exists($f,$data))throw HttpException::unprocessable('Incident field is required.','invalid_'.$f);$data['severity']??='LOW';$data['status']??='OPEN';$data['reported_at']??=date('Y-m-d H:i:s');foreach(['employee_id','reporter_user_id','shift_assignment_id','patrol_session_id','actions_taken','resolution','closed_at']as$f)$data[$f]??=null;}if(isset($data['severity'])&&!in_array($data['severity'],self::SEVERITIES,true))throw HttpException::unprocessable('Incident severity is invalid.','invalid_incident_severity');if(isset($data['status'])&&!in_array($data['status'],self::STATUSES,true))throw HttpException::unprocessable('Incident status is invalid.','invalid_incident_status');foreach(['description'=>65535,'actions_taken'=>65535,'resolution'=>65535]as$f=>$max)if(isset($data[$f])&&$data[$f]!==null&&(!is_string($data[$f])||strlen($data[$f])>$max))throw HttpException::unprocessable('Incident text is invalid.','invalid_'.$f);return$data;}
    private function relationships(array $data):void{if(!$this->incidents->siteExists((string)$data['site_id']))throw HttpException::notFound('Site not found.','site_not_found');if(($data['employee_id']??null)!==null&&!$this->incidents->employeeExists((string)$data['employee_id']))throw HttpException::notFound('Employee not found.','employee_not_found');if(($data['reporter_user_id']??null)!==null&&!$this->incidents->userExists((string)$data['reporter_user_id']))throw HttpException::notFound('Reporter user not found.','reporter_user_not_found');if(($data['shift_assignment_id']??null)!==null){$shift=$this->incidents->shift((string)$data['shift_assignment_id']);if($shift===null)throw HttpException::notFound('Shift assignment not found.','shift_assignment_not_found');if(($data['employee_id']??null)!==null&&(string)$shift['employee_id']!==(string)$data['employee_id'])throw HttpException::unprocessable('Incident employee does not match shift.','invalid_incident_relationship');if((string)$shift['site_id']!==(string)$data['site_id'])throw HttpException::unprocessable('Incident site does not match shift.','invalid_incident_relationship');}if(($data['patrol_session_id']??null)!==null){$patrol=$this->incidents->patrol((string)$data['patrol_session_id']);if($patrol===null)throw HttpException::notFound('Patrol session not found.','patrol_session_not_found');if(($data['employee_id']??null)!==null&&(string)$patrol['employee_id']!==(string)$data['employee_id'])throw HttpException::unprocessable('Incident employee does not match patrol.','invalid_incident_relationship');if((string)$patrol['site_id']!==(string)$data['site_id'])throw HttpException::unprocessable('Incident site does not match patrol.','invalid_incident_relationship');}}
    private function times(array $data):void{$occurred=$this->date($data['occurred_at']??null,'occurred_at');$reported=$this->date($data['reported_at']??null,'reported_at');if($reported<$occurred)throw HttpException::unprocessable('Reported at must not precede occurred at.','invalid_incident_timestamp');if(($data['closed_at']??null)!==null)$this->date($data['closed_at'],'closed_at');}
    private function id(mixed $value,string $field):int{if((!is_int($value)&&!(is_string($value)&&ctype_digit($value)))||(int)$value<1)throw HttpException::unprocessable('Incident identifier is invalid.','invalid_'.$field);return(int)$value;}private function date(mixed $value,string $field):DateTimeImmutable{if(!is_string($value))throw HttpException::unprocessable('Incident timestamp is invalid.','invalid_'.$field);try{return new DateTimeImmutable($value);}catch(\Throwable){throw HttpException::unprocessable('Incident timestamp is invalid.','invalid_'.$field);}}private function actor():?string{$actor=$this->context->user();return is_scalar($actor)?(string)$actor:null;}private function audit(string $action,array $incident):void{try{$this->audit->record('incident',$action,(string)$incident['incident_id'],[],['site_id'=>$incident['site_id'],'status'=>$incident['status'],'severity'=>$incident['severity']]);}catch(\Throwable){}}
}